CREATE TABLE IF NOT EXISTS "members" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Opaque id used in URLs so the sequential primary key is never exposed.
	"public_id" VARCHAR(64) NOT NULL UNIQUE,
	-- Custom profile slug. Nullable because a member can rename it and one is not assigned until onboarding completes.
	"vanity_url" VARCHAR(100) UNIQUE,
	-- Primary login address. 320 chars is the RFC 5321 maximum.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Given name as entered by the member.
	"first_name" VARCHAR(80) NOT NULL,
	-- Family name as entered by the member.
	"last_name" VARCHAR(80) NOT NULL,
	-- The one line under the name. Defaults to the current position title in the UI but is editable, so it is stored rather than derived.
	"headline" VARCHAR(220),
	-- Long-form summary, Markdown.
	"about" TEXT,
	-- Free-text location the member displays, e.g. "Greater Boston Area".
	"location_name" VARCHAR(160),
	-- ISO 3166-1 alpha-2 code, kept alongside the free text so search can filter by country.
	"country_code" CHAR(2),
	-- Self-declared industry. Free text rather than a lookup, because the taxonomy changes faster than the profiles.
	"industry" VARCHAR(120),
	-- CDN URL of the avatar. Null until a photo is uploaded.
	"profile_photo_url" VARCHAR(500),
	-- Drives the recruiter-visible badge and boosts the profile in candidate search.
	"open_to_work" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last profile edit; used to rank freshness in search.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "members" IS 'A person. The profile row holds only the always-true facts; everything that has a start and an end lives in positions or educations.';
COMMENT ON COLUMN "members"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "members"."public_id" IS 'Opaque id used in URLs so the sequential primary key is never exposed.';
COMMENT ON COLUMN "members"."vanity_url" IS 'Custom profile slug. Nullable because a member can rename it and one is not assigned until onboarding completes.';
COMMENT ON COLUMN "members"."email" IS 'Primary login address. 320 chars is the RFC 5321 maximum.';
COMMENT ON COLUMN "members"."first_name" IS 'Given name as entered by the member.';
COMMENT ON COLUMN "members"."last_name" IS 'Family name as entered by the member.';
COMMENT ON COLUMN "members"."headline" IS 'The one line under the name. Defaults to the current position title in the UI but is editable, so it is stored rather than derived.';
COMMENT ON COLUMN "members"."about" IS 'Long-form summary, Markdown.';
COMMENT ON COLUMN "members"."location_name" IS 'Free-text location the member displays, e.g. "Greater Boston Area".';
COMMENT ON COLUMN "members"."country_code" IS 'ISO 3166-1 alpha-2 code, kept alongside the free text so search can filter by country.';
COMMENT ON COLUMN "members"."industry" IS 'Self-declared industry. Free text rather than a lookup, because the taxonomy changes faster than the profiles.';
COMMENT ON COLUMN "members"."profile_photo_url" IS 'CDN URL of the avatar. Null until a photo is uploaded.';
COMMENT ON COLUMN "members"."open_to_work" IS 'Drives the recruiter-visible badge and boosts the profile in candidate search.';
COMMENT ON COLUMN "members"."created_at" IS 'Signup time.';
COMMENT ON COLUMN "members"."updated_at" IS 'Last profile edit; used to rank freshness in search.';

CREATE INDEX "idx_members_country_industry"
ON "members" ("country_code", "industry");
CREATE INDEX "idx_members_updated"
ON "members" ("updated_at");

CREATE TABLE IF NOT EXISTS "companies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Legal or trading name as displayed.
	"name" VARCHAR(200) NOT NULL,
	-- URL segment for the company page.
	"slug" VARCHAR(220) NOT NULL UNIQUE,
	-- Public website. Null for companies created implicitly from a member typing an employer name.
	"website" VARCHAR(300),
	-- Primary industry for company search facets.
	"industry" VARCHAR(120),
	-- self_employed | 1_10 | 11_50 | 51_200 | 201_500 | 501_1000 | 1001_5000 | 5001_plus. Buckets rather than a count, because headcount is never current.
	"size_bucket" VARCHAR(24),
	-- Year of incorporation, when claimed.
	"founded_year" SMALLINT,
	-- True once an admin proved control of the domain; unverified pages are still linkable but not editable.
	"is_verified" BOOLEAN NOT NULL DEFAULT false,
	-- Row creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "companies" IS 'An employer page. Rows are created both by company admins and implicitly when a member types an employer that does not exist yet, which is why most columns are nullable.';
COMMENT ON COLUMN "companies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "companies"."name" IS 'Legal or trading name as displayed.';
COMMENT ON COLUMN "companies"."slug" IS 'URL segment for the company page.';
COMMENT ON COLUMN "companies"."website" IS 'Public website. Null for companies created implicitly from a member typing an employer name.';
COMMENT ON COLUMN "companies"."industry" IS 'Primary industry for company search facets.';
COMMENT ON COLUMN "companies"."size_bucket" IS 'self_employed | 1_10 | 11_50 | 51_200 | 201_500 | 501_1000 | 1001_5000 | 5001_plus. Buckets rather than a count, because headcount is never current.';
COMMENT ON COLUMN "companies"."founded_year" IS 'Year of incorporation, when claimed.';
COMMENT ON COLUMN "companies"."is_verified" IS 'True once an admin proved control of the domain; unverified pages are still linkable but not editable.';
COMMENT ON COLUMN "companies"."created_at" IS 'Row creation time.';

CREATE INDEX "idx_companies_industry_size"
ON "companies" ("industry", "size_bucket");

CREATE TABLE IF NOT EXISTS "schools" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Institution name as displayed.
	"name" VARCHAR(200) NOT NULL,
	-- URL segment for the school page.
	"slug" VARCHAR(220) NOT NULL UNIQUE,
	-- ISO 3166-1 alpha-2 code of the main campus.
	"country_code" CHAR(2),
	-- Row creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "schools" IS 'An educational institution. Kept separate from companies because a school page has no headcount, no job postings and no billing relationship.';
COMMENT ON COLUMN "schools"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "schools"."name" IS 'Institution name as displayed.';
COMMENT ON COLUMN "schools"."slug" IS 'URL segment for the school page.';
COMMENT ON COLUMN "schools"."country_code" IS 'ISO 3166-1 alpha-2 code of the main campus.';
COMMENT ON COLUMN "schools"."created_at" IS 'Row creation time.';

CREATE TABLE IF NOT EXISTS "positions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Whose career history this row belongs to.
	"member_id" BIGINT NOT NULL,
	-- Employer page. Null when the member typed a name that was never resolved to a company row.
	"company_id" BIGINT,
	-- Employer name snapshotted at entry time, so a renamed or merged company page never rewrites someone history.
	"company_name" VARCHAR(200) NOT NULL,
	-- Job title as the member wrote it.
	"title" VARCHAR(200) NOT NULL,
	-- full_time | part_time | contract | internship | freelance | seasonal.
	"employment_type" VARCHAR(24) NOT NULL DEFAULT 'full_time',
	-- Where the job was based. Null for remote-only roles.
	"location_name" VARCHAR(160),
	-- Denormalised from end_date being null. Stored because "current employees of X" is a hot query and indexing a null test is awkward.
	"is_current" BOOLEAN NOT NULL DEFAULT false,
	-- First day. A DATE, not a timestamp: careers are recorded to the month, not the instant.
	"start_date" DATE NOT NULL,
	-- Last day. Null means the role is ongoing, which is the single source of truth for is_current.
	"end_date" DATE,
	-- Achievements and responsibilities, Markdown.
	"description" TEXT,
	-- When the member added the entry.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "positions" IS 'One row per job, closed by an end_date rather than replaced. Overlapping rows are legal and expected - people hold two jobs, and a promotion is a new row at the same company.';
COMMENT ON COLUMN "positions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "positions"."member_id" IS 'Whose career history this row belongs to.';
COMMENT ON COLUMN "positions"."company_id" IS 'Employer page. Null when the member typed a name that was never resolved to a company row.';
COMMENT ON COLUMN "positions"."company_name" IS 'Employer name snapshotted at entry time, so a renamed or merged company page never rewrites someone history.';
COMMENT ON COLUMN "positions"."title" IS 'Job title as the member wrote it.';
COMMENT ON COLUMN "positions"."employment_type" IS 'full_time | part_time | contract | internship | freelance | seasonal.';
COMMENT ON COLUMN "positions"."location_name" IS 'Where the job was based. Null for remote-only roles.';
COMMENT ON COLUMN "positions"."is_current" IS 'Denormalised from end_date being null. Stored because "current employees of X" is a hot query and indexing a null test is awkward.';
COMMENT ON COLUMN "positions"."start_date" IS 'First day. A DATE, not a timestamp: careers are recorded to the month, not the instant.';
COMMENT ON COLUMN "positions"."end_date" IS 'Last day. Null means the role is ongoing, which is the single source of truth for is_current.';
COMMENT ON COLUMN "positions"."description" IS 'Achievements and responsibilities, Markdown.';
COMMENT ON COLUMN "positions"."created_at" IS 'When the member added the entry.';

CREATE INDEX "idx_positions_member_start"
ON "positions" ("member_id", "start_date");
CREATE INDEX "idx_positions_company_current"
ON "positions" ("company_id", "is_current");

CREATE TABLE IF NOT EXISTS "educations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Whose education history this row belongs to.
	"member_id" BIGINT NOT NULL,
	-- School page. Null when the institution was typed free-hand.
	"school_id" BIGINT,
	-- Institution name snapshotted at entry time, for the same reason positions snapshot the employer.
	"school_name" VARCHAR(200) NOT NULL,
	-- Awarded degree, e.g. "BSc". Null for unfinished or non-degree study.
	"degree" VARCHAR(160),
	-- Major or subject area.
	"field_of_study" VARCHAR(160),
	-- Final grade or classification, free text because grading systems differ per country.
	"grade" VARCHAR(40),
	-- Matriculation date, to the month. Nullable because members often remember only the graduation year.
	"start_date" DATE,
	-- Graduation or expected graduation. Null means still studying.
	"end_date" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "educations" IS 'The same time-boxed shape as positions, deliberately kept as its own table: the columns that matter (degree, field, grade) have no analogue in employment.';
COMMENT ON COLUMN "educations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "educations"."member_id" IS 'Whose education history this row belongs to.';
COMMENT ON COLUMN "educations"."school_id" IS 'School page. Null when the institution was typed free-hand.';
COMMENT ON COLUMN "educations"."school_name" IS 'Institution name snapshotted at entry time, for the same reason positions snapshot the employer.';
COMMENT ON COLUMN "educations"."degree" IS 'Awarded degree, e.g. "BSc". Null for unfinished or non-degree study.';
COMMENT ON COLUMN "educations"."field_of_study" IS 'Major or subject area.';
COMMENT ON COLUMN "educations"."grade" IS 'Final grade or classification, free text because grading systems differ per country.';
COMMENT ON COLUMN "educations"."start_date" IS 'Matriculation date, to the month. Nullable because members often remember only the graduation year.';
COMMENT ON COLUMN "educations"."end_date" IS 'Graduation or expected graduation. Null means still studying.';

CREATE INDEX "idx_educations_member_end"
ON "educations" ("member_id", "end_date");

CREATE TABLE IF NOT EXISTS "skills" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Canonical skill name. Unique, so "PostgreSQL" is one node in the graph and not one per profile.
	"name" VARCHAR(120) NOT NULL UNIQUE,
	-- URL segment for the skill page.
	"slug" VARCHAR(140) NOT NULL UNIQUE,
	-- Row creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "skills" IS 'The controlled vocabulary. Keeping skills canonical is what makes "members who know X" a single indexed join instead of a text search across profiles.';
COMMENT ON COLUMN "skills"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "skills"."name" IS 'Canonical skill name. Unique, so "PostgreSQL" is one node in the graph and not one per profile.';
COMMENT ON COLUMN "skills"."slug" IS 'URL segment for the skill page.';
COMMENT ON COLUMN "skills"."created_at" IS 'Row creation time.';

CREATE TABLE IF NOT EXISTS "member_skills" (
	-- Surrogate primary key. A join table would normally use a composite key, but endorsements point at this row, so it carries its own id.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Member claiming the skill.
	"member_id" BIGINT NOT NULL,
	-- Skill claimed.
	"skill_id" BIGINT NOT NULL,
	-- Manual ordering on the profile; the top three are the ones that show without expanding.
	"position_index" SMALLINT NOT NULL DEFAULT 0,
	-- Denormalised count of endorsements. Maintained on write because the profile renders it on every view and the exact number is not load-bearing.
	"endorsement_count" INTEGER NOT NULL DEFAULT 0,
	-- When the skill was added to the profile.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "member_skills" IS 'A claimed skill. The claim and the social proof are separate: this row exists with zero endorsements, which is the normal case.';
COMMENT ON COLUMN "member_skills"."id" IS 'Surrogate primary key. A join table would normally use a composite key, but endorsements point at this row, so it carries its own id.';
COMMENT ON COLUMN "member_skills"."member_id" IS 'Member claiming the skill.';
COMMENT ON COLUMN "member_skills"."skill_id" IS 'Skill claimed.';
COMMENT ON COLUMN "member_skills"."position_index" IS 'Manual ordering on the profile; the top three are the ones that show without expanding.';
COMMENT ON COLUMN "member_skills"."endorsement_count" IS 'Denormalised count of endorsements. Maintained on write because the profile renders it on every view and the exact number is not load-bearing.';
COMMENT ON COLUMN "member_skills"."created_at" IS 'When the skill was added to the profile.';

CREATE UNIQUE INDEX "uq_member_skills_member_skill"
ON "member_skills" ("member_id", "skill_id");
CREATE INDEX "idx_member_skills_skill"
ON "member_skills" ("skill_id");

CREATE TABLE IF NOT EXISTS "endorsements" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The claimed skill being vouched for, not the member - endorsing "Ana for SQL" is meaningless if Ana removes SQL from her profile.
	"member_skill_id" BIGINT NOT NULL,
	-- Member doing the endorsing.
	"endorser_id" BIGINT NOT NULL,
	-- When the endorsement was given; the profile shows the most recent endorsers first.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "endorsements" IS 'One vouch from one member for one claimed skill. The unique constraint is the whole anti-spam story: endorsing twice is a no-op at the database level.';
COMMENT ON COLUMN "endorsements"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "endorsements"."member_skill_id" IS 'The claimed skill being vouched for, not the member - endorsing "Ana for SQL" is meaningless if Ana removes SQL from her profile.';
COMMENT ON COLUMN "endorsements"."endorser_id" IS 'Member doing the endorsing.';
COMMENT ON COLUMN "endorsements"."created_at" IS 'When the endorsement was given; the profile shows the most recent endorsers first.';

CREATE UNIQUE INDEX "uq_endorsements_skill_endorser"
ON "endorsements" ("member_skill_id", "endorser_id");
CREATE INDEX "idx_endorsements_endorser"
ON "endorsements" ("endorser_id");

CREATE TABLE IF NOT EXISTS "invitations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Member who asked to connect.
	"sender_id" BIGINT NOT NULL,
	-- Member who was asked.
	"recipient_id" BIGINT NOT NULL,
	-- pending | accepted | declined | withdrawn | expired. Terminal rows are kept so a declined sender cannot immediately re-ask.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- Optional note attached to the request.
	"message" VARCHAR(300),
	-- When the request was sent.
	"sent_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When the recipient acted. Null while pending.
	"responded_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "invitations" IS 'The directed half of connecting. An invitation has a sender and a recipient and therefore a direction; the connection it produces does not.';
COMMENT ON COLUMN "invitations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "invitations"."sender_id" IS 'Member who asked to connect.';
COMMENT ON COLUMN "invitations"."recipient_id" IS 'Member who was asked.';
COMMENT ON COLUMN "invitations"."status" IS 'pending | accepted | declined | withdrawn | expired. Terminal rows are kept so a declined sender cannot immediately re-ask.';
COMMENT ON COLUMN "invitations"."message" IS 'Optional note attached to the request.';
COMMENT ON COLUMN "invitations"."sent_at" IS 'When the request was sent.';
COMMENT ON COLUMN "invitations"."responded_at" IS 'When the recipient acted. Null while pending.';

CREATE INDEX "idx_invitations_recipient_status"
ON "invitations" ("recipient_id", "status");
CREATE INDEX "idx_invitations_pair_status"
ON "invitations" ("sender_id", "recipient_id", "status");

CREATE TABLE IF NOT EXISTS "connections" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Lower of the two member ids. The ordering is a storage convention, not a role.
	"member_a_id" BIGINT NOT NULL,
	-- Higher of the two member ids, enforced by a check so the same pair cannot be stored twice.
	"member_b_id" BIGINT NOT NULL,
	-- The accepted invitation that created this edge. Null for legacy or admin-created links.
	"invitation_id" BIGINT,
	-- When the invitation was accepted; drives "connected since" and degree-of-separation caching.
	"connected_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "connections" IS 'A symmetric edge stored once with the ids sorted. One row per friendship keeps the unique constraint honest; reading a member connections means checking both columns, which the second index covers.';
COMMENT ON COLUMN "connections"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "connections"."member_a_id" IS 'Lower of the two member ids. The ordering is a storage convention, not a role.';
COMMENT ON COLUMN "connections"."member_b_id" IS 'Higher of the two member ids, enforced by a check so the same pair cannot be stored twice.';
COMMENT ON COLUMN "connections"."invitation_id" IS 'The accepted invitation that created this edge. Null for legacy or admin-created links.';
COMMENT ON COLUMN "connections"."connected_at" IS 'When the invitation was accepted; drives "connected since" and degree-of-separation caching.';

CREATE UNIQUE INDEX "uq_connections_pair"
ON "connections" ("member_a_id", "member_b_id");
CREATE INDEX "idx_connections_member_b"
ON "connections" ("member_b_id");

CREATE TABLE IF NOT EXISTS "job_postings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Hiring company.
	"company_id" BIGINT NOT NULL,
	-- Recruiter who created the posting. Null once that person leaves and their account is closed.
	"posted_by_member_id" BIGINT,
	-- Advertised job title.
	"title" VARCHAR(200) NOT NULL,
	-- Full posting body, Markdown.
	"description" TEXT NOT NULL,
	-- Advertised location. Null for fully remote roles.
	"location_name" VARCHAR(160),
	-- onsite | hybrid | remote.
	"workplace_type" VARCHAR(16) NOT NULL DEFAULT 'onsite',
	-- full_time | part_time | contract | internship | freelance.
	"employment_type" VARCHAR(24) NOT NULL DEFAULT 'full_time',
	-- Bottom of the advertised range in minor units. Integer money, never float.
	"salary_min_minor" INTEGER,
	-- Top of the advertised range in minor units.
	"salary_max_minor" INTEGER,
	-- ISO 4217 currency for the salary range. Null when no range is advertised.
	"currency_code" CHAR(3),
	-- draft | open | paused | closed | filled.
	"status" VARCHAR(16) NOT NULL DEFAULT 'open',
	-- Publication time; feeds the "posted 3 days ago" label and search recency.
	"posted_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Automatic close time. Null means the posting stays open until a human closes it.
	"closes_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "job_postings" IS 'An open role. Salary is a nullable range in minor units because most postings advertise no number and the ones that do advertise a band, not a figure.';
COMMENT ON COLUMN "job_postings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "job_postings"."company_id" IS 'Hiring company.';
COMMENT ON COLUMN "job_postings"."posted_by_member_id" IS 'Recruiter who created the posting. Null once that person leaves and their account is closed.';
COMMENT ON COLUMN "job_postings"."title" IS 'Advertised job title.';
COMMENT ON COLUMN "job_postings"."description" IS 'Full posting body, Markdown.';
COMMENT ON COLUMN "job_postings"."location_name" IS 'Advertised location. Null for fully remote roles.';
COMMENT ON COLUMN "job_postings"."workplace_type" IS 'onsite | hybrid | remote.';
COMMENT ON COLUMN "job_postings"."employment_type" IS 'full_time | part_time | contract | internship | freelance.';
COMMENT ON COLUMN "job_postings"."salary_min_minor" IS 'Bottom of the advertised range in minor units. Integer money, never float.';
COMMENT ON COLUMN "job_postings"."salary_max_minor" IS 'Top of the advertised range in minor units.';
COMMENT ON COLUMN "job_postings"."currency_code" IS 'ISO 4217 currency for the salary range. Null when no range is advertised.';
COMMENT ON COLUMN "job_postings"."status" IS 'draft | open | paused | closed | filled.';
COMMENT ON COLUMN "job_postings"."posted_at" IS 'Publication time; feeds the "posted 3 days ago" label and search recency.';
COMMENT ON COLUMN "job_postings"."closes_at" IS 'Automatic close time. Null means the posting stays open until a human closes it.';

CREATE INDEX "idx_job_postings_company_status"
ON "job_postings" ("company_id", "status");
CREATE INDEX "idx_job_postings_status_posted"
ON "job_postings" ("status", "posted_at");

CREATE TABLE IF NOT EXISTS "job_applications" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Role applied to.
	"job_posting_id" BIGINT NOT NULL,
	-- Member who applied.
	"applicant_id" BIGINT NOT NULL,
	-- submitted | viewed | shortlisted | rejected | withdrawn | hired.
	"status" VARCHAR(24) NOT NULL DEFAULT 'submitted',
	-- Optional message to the recruiter.
	"cover_note" TEXT,
	-- Object-store URL of the uploaded CV. Null when the member applied with their profile only.
	"resume_url" VARCHAR(500),
	-- The applicant headline at the moment of applying, so the recruiter pipeline does not change under them when the member edits their profile.
	"headline_snapshot" VARCHAR(220),
	-- Submission time.
	"applied_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last pipeline movement; drives recruiter SLA reporting.
	"status_changed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "job_applications" IS 'One application per member per posting, enforced by the unique index. The snapshotted headline is what keeps a recruiter shortlist stable while profiles keep changing.';
COMMENT ON COLUMN "job_applications"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "job_applications"."job_posting_id" IS 'Role applied to.';
COMMENT ON COLUMN "job_applications"."applicant_id" IS 'Member who applied.';
COMMENT ON COLUMN "job_applications"."status" IS 'submitted | viewed | shortlisted | rejected | withdrawn | hired.';
COMMENT ON COLUMN "job_applications"."cover_note" IS 'Optional message to the recruiter.';
COMMENT ON COLUMN "job_applications"."resume_url" IS 'Object-store URL of the uploaded CV. Null when the member applied with their profile only.';
COMMENT ON COLUMN "job_applications"."headline_snapshot" IS 'The applicant headline at the moment of applying, so the recruiter pipeline does not change under them when the member edits their profile.';
COMMENT ON COLUMN "job_applications"."applied_at" IS 'Submission time.';
COMMENT ON COLUMN "job_applications"."status_changed_at" IS 'Last pipeline movement; drives recruiter SLA reporting.';

CREATE UNIQUE INDEX "uq_applications_posting_applicant"
ON "job_applications" ("job_posting_id", "applicant_id");
CREATE INDEX "idx_applications_applicant_applied"
ON "job_applications" ("applicant_id", "applied_at");

CREATE TABLE IF NOT EXISTS "posts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Member who published the post.
	"author_id" BIGINT NOT NULL,
	-- The post being reshared. Null for an original post; a self-reference is how a repost keeps pointing at the original body.
	"shared_post_id" BIGINT,
	-- Post text, Markdown. Null when a bare reshare adds no commentary.
	"body" TEXT,
	-- Attached image, video or document. Null for a text-only post.
	"media_url" VARCHAR(500),
	-- public | connections | group. Evaluated against the connections table at read time.
	"visibility" VARCHAR(16) NOT NULL DEFAULT 'public',
	-- Denormalised total across all reaction types, maintained on write for feed rendering.
	"reaction_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised comment total, same reasoning.
	"comment_count" INTEGER NOT NULL DEFAULT 0,
	-- Publication time; the feed is ordered by this within a relevance window.
	"published_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Soft delete. Set rather than removing the row, so reshares pointing here do not dangle.
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "posts" IS 'A feed item. Reshares are posts with a parent rather than a separate table, which means one query renders a mixed feed of originals and reposts.';
COMMENT ON COLUMN "posts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "posts"."author_id" IS 'Member who published the post.';
COMMENT ON COLUMN "posts"."shared_post_id" IS 'The post being reshared. Null for an original post; a self-reference is how a repost keeps pointing at the original body.';
COMMENT ON COLUMN "posts"."body" IS 'Post text, Markdown. Null when a bare reshare adds no commentary.';
COMMENT ON COLUMN "posts"."media_url" IS 'Attached image, video or document. Null for a text-only post.';
COMMENT ON COLUMN "posts"."visibility" IS 'public | connections | group. Evaluated against the connections table at read time.';
COMMENT ON COLUMN "posts"."reaction_count" IS 'Denormalised total across all reaction types, maintained on write for feed rendering.';
COMMENT ON COLUMN "posts"."comment_count" IS 'Denormalised comment total, same reasoning.';
COMMENT ON COLUMN "posts"."published_at" IS 'Publication time; the feed is ordered by this within a relevance window.';
COMMENT ON COLUMN "posts"."deleted_at" IS 'Soft delete. Set rather than removing the row, so reshares pointing here do not dangle.';

CREATE INDEX "idx_posts_author_published"
ON "posts" ("author_id", "published_at");
CREATE INDEX "idx_posts_published"
ON "posts" ("published_at");

